class signal;

typedef unsigned int size_t;

template <class T>
class my_allocator
{
public:
  T* allocate(size_t);
  void deallocate(T*, size_t);
};

template <class T, class Alloc>
class vector
{
public:
  typedef T* iterator;
  typedef unsigned int size_type;

  iterator _M_start;
  iterator _M_finish;
  iterator _M_end_of_storage;

  void _M_insert_aux(iterator, const T&)
    __asm__("_M_insert_aux__t6vector2ZP6signalZt12my_allocator1ZP6signalPP6signalRCP6signal");

private:
  Alloc _M_allocator;

  iterator _M_allocate(size_type n)
  {
    return n ? _M_allocator.allocate(n) : 0;
  }

  void _M_deallocate(iterator p, size_type n)
  {
    if (p)
      _M_allocator.deallocate(p, n);
  }
};

template <class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T& x)
{
  if (_M_finish != _M_end_of_storage)
  {
    *_M_finish = *(_M_finish - 1);
    ++_M_finish;
    T x_copy = x;
    iterator first = position;
    iterator last = _M_finish - 2;
    iterator result = _M_finish - 1;
    while (last != first)
      *--result = *--last;
    *position = x_copy;
  }
  else
  {
    size_type old_size = _M_finish - _M_start;
    size_type len = old_size != 0 ? 2 * old_size : 1;
    iterator new_start = _M_allocate(len);
    iterator new_finish = new_start;
    iterator cur = _M_start;
    while (cur != position)
      *new_finish++ = *cur++;
    *new_finish++ = x;
    while (cur != _M_finish)
      *new_finish++ = *cur++;
    _M_deallocate(_M_start, _M_end_of_storage - _M_start);
    _M_start = new_start;
    _M_finish = new_finish;
    _M_end_of_storage = new_start + len;
  }
}

template void vector<signal*, my_allocator<signal*> >::_M_insert_aux(signal**, signal* const&);
